203	    async fn auth_publickey(&mut self, user: &str, key: &PublicKey) -> Result<Auth, Self::Error> {
204	        let Some(key_line) = devices::public_key_line(key) else {
205	            eprintln!("[local-sync] auth rejected: unreadable public key");
206	            return Ok(reject());
207	        };
208	        let key_preview = &key_line[key_line.len().saturating_sub(12)..];
209	        if devices::is_authorized(&self.shared.devices_path, &key_line) {
210	            eprintln!(
211	                "[local-sync] auth ok: paired device key (…{key_preview}) as '{}'",
212	                pairing_user_for_log(user)
213	            );
214	            return Ok(Auth::Accept);
215	        }
216	        match pairing_token_match(
217	            user,
218	            &self.shared.pairing_token,
219	            &self.shared.consumed_pairing_tokens,
220	        ) {
221	            PairingTokenMatch::Current(matched_token) => {
222	                let name = devices::device_name_from_key(key);
223	                match devices::register_device(&self.shared.devices_path, &key_line, &name) {
224	                    Ok(()) => {
225	                        // Rotate for the desktop QR, but leave the consumed token
226	                        // usable for a short grace period. The mobile setup path can
227	                        // otherwise expire its own QR between connect and first pull.
228	                        let consumed_suffix = pairing_token_suffix(&matched_token);
229	                        remember_consumed_pairing_token(
230	                            &self.shared.consumed_pairing_tokens,
231	                            matched_token,
232	                        );
233	                        let fresh = devices::rotate_pairing_token(&self.shared.pairing_token_path);
234	                        let fresh_suffix = pairing_token_suffix(&fresh);
235	                        *self.shared.pairing_token.lock().unwrap() = fresh;
236	                        eprintln!(
237	                            "[local-sync] paired new device '{name}' (…{key_preview}) with current QR token pair-<token:{consumed_suffix}>; rotated to pair-<token:{fresh_suffix}>"
238	                        );
239	                        return Ok(Auth::Accept);
240	                    }
241	                    Err(error) => {
242	                        eprintln!(
243	                            "[local-sync] pairing failed: could not store the device key: {error}"
244	                        );
245	                        return Ok(reject());
246	                    }
247	                }
248	            }
249	            PairingTokenMatch::RecentlyConsumed => {
250	                let name = devices::device_name_from_key(key);
251	                match devices::register_device(&self.shared.devices_path, &key_line, &name) {
252	                    Ok(()) => {
253	                        eprintln!(
254	                            "[local-sync] paired new device '{name}' (…{key_preview}) with recently consumed QR token '{}'",
255	                            pairing_user_for_log(user)
256	                        );
257	                        return Ok(Auth::Accept);
258	                    }
259	                    Err(error) => {
260	                        eprintln!(
261	                            "[local-sync] pairing failed: could not store the device key: {error}"
262	                        );
263	                        return Ok(reject());
264	                    }
265	                }
266	            }
267	            PairingTokenMatch::None => {}
268	        }
269	        eprintln!(
270	            "[local-sync] auth rejected: unknown key (…{key_preview}), username '{}' does not match current/recent pairing token (recent_grace_tokens={}) — re-scan the QR code",
271	            pairing_user_for_log(user),
272	            recent_pairing_token_count(&self.shared.consumed_pairing_tokens)
273	        );
